import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.config import Config


def _flatten_text(blocks_by_id: Dict[str, Dict[str, Any]], relationship_ids: List[str]) -> str:
    parts: List[str] = []
    for rid in relationship_ids:
        child = blocks_by_id.get(rid)
        if not child:
            continue
        if child.get("BlockType") == "WORD":
            parts.append(child.get("Text", ""))
        elif child.get("BlockType") == "SELECTION_ELEMENT":
            if child.get("SelectionStatus") == "SELECTED":
                parts.append("[X]")
            else:
                parts.append("[ ]")
    return " ".join(p for p in parts if p).strip()


def _bbox(block: Dict[str, Any]) -> Optional[Dict[str, float]]:
    geom = block.get("Geometry", {})
    bb = geom.get("BoundingBox")
    if not bb:
        return None
    return {
        "left": bb.get("Left", 0.0),
        "top": bb.get("Top", 0.0),
        "width": bb.get("Width", 0.0),
        "height": bb.get("Height", 0.0),
    }


def extract_layout_from_document(
    file_path: str,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    client = boto3.client(
        "textract",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
        config=Config(retries={"max_attempts": 10, "mode": "standard"}),
    )

    with open(file_path, "rb") as f:
        document_bytes = f.read()

    response = client.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=["TABLES", "FORMS", "LAYOUT"],
    )

    blocks: List[Dict[str, Any]] = response.get("Blocks", [])
    blocks_by_id: Dict[str, Dict[str, Any]] = {b["Id"]: b for b in blocks if "Id" in b}

    pages: List[Dict[str, Any]] = []
    lines: List[Dict[str, Any]] = []
    words: List[Dict[str, Any]] = []
    tables: List[Dict[str, Any]] = []
    key_values: List[Dict[str, Any]] = []
    layout_elements: List[Dict[str, Any]] = []

    key_blocks: Dict[str, Dict[str, Any]] = {}
    value_blocks: Dict[str, Dict[str, Any]] = {}

    for block in blocks:
        block_type = block.get("BlockType")

        if block_type == "PAGE":
            pages.append(
                {
                    "id": block.get("Id"),
                    "page": block.get("Page", 1),
                    "bbox": _bbox(block),
                }
            )

        elif block_type == "LINE":
            lines.append(
                {
                    "id": block.get("Id"),
                    "page": block.get("Page", 1),
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "bbox": _bbox(block),
                }
            )

        elif block_type == "WORD":
            words.append(
                {
                    "id": block.get("Id"),
                    "page": block.get("Page", 1),
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "bbox": _bbox(block),
                }
            )

        elif block_type == "TABLE":
            tables.append(
                {
                    "id": block.get("Id"),
                    "page": block.get("Page", 1),
                    "bbox": _bbox(block),
                    "rows": [],
                }
            )

        elif block_type == "KEY_VALUE_SET":
            entity_types = block.get("EntityTypes", [])
            if "KEY" in entity_types:
                key_blocks[block["Id"]] = block
            elif "VALUE" in entity_types:
                value_blocks[block["Id"]] = block

        elif block_type.startswith("LAYOUT_"):
            layout_elements.append(
                {
                    "id": block.get("Id"),
                    "type": block_type,
                    "page": block.get("Page", 1),
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "bbox": _bbox(block),
                }
            )

    table_index = {t["id"]: t for t in tables}
    cell_blocks = [b for b in blocks if b.get("BlockType") == "CELL"]

    for cell in cell_blocks:
        text = ""
        for rel in cell.get("Relationships", []):
            if rel.get("Type") == "CHILD":
                text = _flatten_text(blocks_by_id, rel.get("Ids", []))
                break

        parent_table_id = None
        for rel in cell.get("Relationships", []):
            if rel.get("Type") == "CHILD":
                continue

        for block in blocks:
            if block.get("BlockType") == "TABLE":
                for rel in block.get("Relationships", []):
                    if rel.get("Type") == "CHILD" and cell.get("Id") in rel.get("Ids", []):
                        parent_table_id = block.get("Id")
                        break
                if parent_table_id:
                    break

        if not parent_table_id or parent_table_id not in table_index:
            continue

        table = table_index[parent_table_id]
        row_index = int(cell.get("RowIndex", 1))
        col_index = int(cell.get("ColumnIndex", 1))

        while len(table["rows"]) < row_index:
            table["rows"].append([])

        row = table["rows"][row_index - 1]
        while len(row) < col_index:
            row.append("")

        row[col_index - 1] = text

    for key_id, key_block in key_blocks.items():
        key_text = ""
        value_text = ""

        for rel in key_block.get("Relationships", []):
            if rel.get("Type") == "CHILD":
                key_text = _flatten_text(blocks_by_id, rel.get("Ids", []))
            elif rel.get("Type") == "VALUE":
                for value_id in rel.get("Ids", []):
                    value_block = value_blocks.get(value_id)
                    if not value_block:
                        continue
                    for vrel in value_block.get("Relationships", []):
                        if vrel.get("Type") == "CHILD":
                            value_text = _flatten_text(blocks_by_id, vrel.get("Ids", []))
                            break

        key_values.append(
            {
                "id": key_id,
                "page": key_block.get("Page", 1),
                "key": key_text,
                "value": value_text,
                "confidence": key_block.get("Confidence"),
                "bbox": _bbox(key_block),
            }
        )

    return {
        "provider": "aws_textract",
        "model_family": "Amazon Textract AnalyzeDocument",
        "pages": pages,
        "lines": lines,
        "words": words,
        "tables": tables,
        "key_values": key_values,
        "layout_elements": layout_elements,
        "raw_block_count": len(blocks),
    }
